window.BEACHES=[{"stop": 2, "area": "Castiglione del Lago", "name": "Lido comunale and Lungolago (lakeside beach and promenade)", "what": "A grassy lakeside lawn with shade trees, a small sand/grass beach (Pescatore Cafè Praia at the Lido comunale) and a flat, paved lakeside path, the Lungolago. It runs about 2 km from the ferry pier to Camping Listro, with benches and bars. Very easy walking. The lake has been low in recent years, so the water's edge can sit well out from the shore.", "from": "Le Macerine", "how": "Walk about 0.95 km, around 13 min east down to the lake. The ferry pier for Isola Maggiore is 1.2 km (15 min).", "lat": 43.1235421, "lon": 12.0556358, "photos": [{"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Castiglione_del_Lago_-_Via_Lungolago_01.jpg/960px-Castiglione_del_Lago_-_Via_Lungolago_01.jpg", "p": "https://commons.wikimedia.org/wiki/File:Castiglione_del_Lago_-_Via_Lungolago_01.jpg", "b": "Walter Giannetti", "l": "CC BY-SA 4.0"}, {"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Castiglione_del_Lago_-_Lago_Trasimeno_5_Pier.jpg/960px-Castiglione_del_Lago_-_Lago_Trasimeno_5_Pier.jpg", "p": "https://commons.wikimedia.org/wiki/File:Castiglione_del_Lago_-_Lago_Trasimeno_5_Pier.jpg", "b": "Wolfgang Sauber", "l": "CC BY-SA 4.0"}]}, {"stop": 4, "area": "Montesilvano", "name": "Montesilvano seafront, accessible free beach on Viale Aldo Moro", "what": "Wide, flat, fine-sand Adriatic beach with a long palm-lined promenade and cycle path (Viale Aldo Moro) and benches. This free section has wheelchair mats, beach wheelchairs and free toilets, with cafés beside it (Cafè del Mare, La Rosa dei Venti). Most beach clubs close in October, but the promenade stays open for walking.", "from": "Centoquindici Rooms & Suite, Corso Umberto I 115", "how": "Walk about 1.1 km, around 15 min, roughly east to the sea and passing under the railway. Montesilvano station is about the same distance (1.07 km, 14 min). The access point is the disabled parking bay on Viale Aldo Moro right at the beach.", "lat": 42.5179002, "lon": 14.1605857, "photos": [{"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/Riviera_montesilvano.jpg/960px-Riviera_montesilvano.jpg", "p": "https://commons.wikimedia.org/wiki/File:Riviera_montesilvano.jpg", "b": "Comune di Montesilvano", "l": "CC BY-SA 3.0"}, {"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Spiaggia_montesilvano.jpg/960px-Spiaggia_montesilvano.jpg", "p": "https://commons.wikimedia.org/wiki/File:Spiaggia_montesilvano.jpg", "b": "Comune di Montesilvano", "l": "CC BY-SA 3.0"}]}, {"stop": 4, "area": "Pescara", "name": "Pescara central beach at Piazza Primo Maggio (Nave di Cascella)", "what": "The city's main sandy beach, at the sea end of Corso Umberto I beside the Nave di Cascella ship fountain. A flat, paved promenade (Lungomare Matteotti) with benches runs both ways, plus plenty of cafés. There is a free public stretch right here. Easy level walking.", "from": "Pescara Centrale station", "how": "Walk about 0.9 km, around 12 min straight down Corso Umberto I, the pedestrian shopping street, to the sea.", "lat": 42.4736265, "lon": 14.211468, "photos": [{"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/Spiaggia_Pescara.jpg/960px-Spiaggia_Pescara.jpg", "p": "https://commons.wikimedia.org/wiki/File:Spiaggia_Pescara.jpg", "b": "Alan & Flora Botting", "l": "CC BY-SA 2.0"}, {"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Pescara_lungomare_centro_03_%28raboe%29.jpg/960px-Pescara_lungomare_centro_03_%28raboe%29.jpg", "p": "https://commons.wikimedia.org/wiki/File:Pescara_lungomare_centro_03_(raboe).jpg", "b": "Ra Boe", "l": "CC BY-SA 3.0"}]}, {"stop": 4, "area": "Trabocchi coast (San Vito Chietino)", "name": "San Vito Marina: Spiaggia di Maruccio at the old station", "what": "The easiest Trabocchi stop. A gravel-and-sand beach in the little harbour village of San Vito Marina, with trabocchi fishing platforms in view (Trabocco Punta Fornace is about 250 m away). You park on the old railway-station square right behind the beach. The Via Verde, a flat car-free path along the old railway line, runs past it. There are cafés and restaurants in the village.", "from": "Montesilvano (car day, Oct 12)", "how": "By car, about 58 km and roughly 45 min south. Park at the old San Vito-Lanciano station square (ex stazione) on the seafront. The beach is about 70 m away.", "lat": 42.3072627, "lon": 14.4479688, "photos": [{"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Spiaggia_di_San_Vito_Chietino_-_panoramio.jpg/960px-Spiaggia_di_San_Vito_Chietino_-_panoramio.jpg", "p": "https://commons.wikimedia.org/wiki/File:Spiaggia_di_San_Vito_Chietino_-_panoramio.jpg", "b": "maury3001", "l": "CC BY 3.0"}, {"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/San_Vito_Marina_%28San_Vito_Chietino%2C_Abruzzo%29_01.jpg/960px-San_Vito_Marina_%28San_Vito_Chietino%2C_Abruzzo%29_01.jpg", "p": "https://commons.wikimedia.org/wiki/File:San_Vito_Marina_(San_Vito_Chietino,_Abruzzo)_01.jpg", "b": "Syrio", "l": "CC BY-SA 4.0"}]}, {"stop": 4, "area": "Trabocchi coast (Fossacesia)", "name": "Fossacesia Marina beach and Trabocco Punta Rocciosa", "what": "A white-pebble beach where the Via Verde, a flat, paved car-free path on the old railway, runs right along the sea. It is an easy level walk of about 350 m north to the Trabocco Punta Rocciosa fishing platform. Seasonal beach clubs, and free parking along Via Lungomare. The abbey of San Giovanni in Venere is on the hill above, a short drive away.", "from": "San Vito Marina (same car day)", "how": "By car, about 9 km and roughly 15 min south. Park on Via Lungomare by the old Fossacesia station (ex stazione) and step onto the Via Verde. The beach is right there.", "lat": 42.2529024, "lon": 14.506844, "photos": [{"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/Fossacesia_Marina-Barca_da_Pesca_sulla_Spiaggia_-_panoramio.jpg/960px-Fossacesia_Marina-Barca_da_Pesca_sulla_Spiaggia_-_panoramio.jpg", "p": "https://commons.wikimedia.org/wiki/File:Fossacesia_Marina-Barca_da_Pesca_sulla_Spiaggia_-_panoramio.jpg", "b": "maury3001", "l": "CC BY 3.0"}, {"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/La_baia_di_Fossacesia_Marina_coi_Trabocchi_-_panoramio.jpg/960px-La_baia_di_Fossacesia_Marina_coi_Trabocchi_-_panoramio.jpg", "p": "https://commons.wikimedia.org/wiki/File:La_baia_di_Fossacesia_Marina_coi_Trabocchi_-_panoramio.jpg", "b": "maury3001", "l": "CC BY 3.0"}]}, {"stop": 5, "area": "Gallipoli", "name": "Spiaggia della Purità (old-town beach)", "what": "A small, sheltered sandy cove right under the old-town sea walls, next to the Purità church. It is famous for sunsets. A stone ramp and steps lead down from the Riviera Nazario Sauro walkway. There are no facilities on the sand, but cafés and restaurants are a few steps away. The flat sea-wall walk around the old town is the easiest part for older walkers.", "from": "Gallipoli station", "how": "Walk about 1.5 km, around 20 min west over the bridge into the old town, then round to the church of Santa Maria della Purità. A short taxi ride is the alternative.", "lat": 40.0558318, "lon": 17.9741362, "photos": [{"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Gallipoli_-_Spiaggia_della_Purit%C3%A0.jpg/960px-Gallipoli_-_Spiaggia_della_Purit%C3%A0.jpg", "p": "https://commons.wikimedia.org/wiki/File:Gallipoli_-_Spiaggia_della_Purit%C3%A0.jpg", "b": "Benjamin Smith", "l": "CC BY-SA 4.0"}, {"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Spiaggia_della_Purit%C3%A0_%28Gallipoli%29.jpg/960px-Spiaggia_della_Purit%C3%A0_%28Gallipoli%29.jpg", "p": "https://commons.wikimedia.org/wiki/File:Spiaggia_della_Purit%C3%A0_(Gallipoli).jpg", "b": "Patrice78500", "l": "CC BY-SA 4.0"}]}, {"stop": 5, "area": "Gallipoli", "name": "Baia Verde (optional)", "what": "A long, shallow, white-sand beach south of the town, backed by pines and beach clubs, many of which close by mid-October. Good for a long flat walk on firm sand at the water's edge. Much bigger and quieter than the town beach out of season.", "from": "Gallipoli station", "how": "Too far to walk comfortably (4.3 km, about 57 min). Take a short taxi of about 10 min, then return the same way.", "lat": 40.032007, "lon": 18.01623, "photos": [{"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Gallipoli%2C_Baia_Verde_%281%29.jpg/960px-Gallipoli%2C_Baia_Verde_%281%29.jpg", "p": "https://commons.wikimedia.org/wiki/File:Gallipoli,_Baia_Verde_(1).jpg", "b": "Palickap", "l": "CC BY-SA 4.0"}, {"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Gallipoli%2C_Baia_Verde_%282%29.jpg/960px-Gallipoli%2C_Baia_Verde_%282%29.jpg", "p": "https://commons.wikimedia.org/wiki/File:Gallipoli,_Baia_Verde_(2).jpg", "b": "Palickap", "l": "CC BY-SA 4.0"}]}, {"stop": 5, "area": "Otranto", "name": "Spiaggia dei Gradoni / degli Scaloni (town beach) and Lungomare degli Eroi", "what": "A small, sandy town beach with clear, shallow water. It is set below the seafront promenade and reached by wide stone steps (the name means \"big steps\"), with bars and gelaterie right behind it. The flat Lungomare degli Eroi promenade continues about 400 m to the old-town walls and castle, and is the easy walk for older legs.", "from": "Otranto station", "how": "Walk about 0.9 km, around 12 min downhill to the seafront. The Lungomare degli Eroi by the old town is 1.1 km (14 min) from the station.", "lat": 40.149141, "lon": 18.487281, "photos": [{"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/L08_020_Otranto%2C_Stadtstrand.jpg/960px-L08_020_Otranto%2C_Stadtstrand.jpg", "p": "https://commons.wikimedia.org/wiki/File:L08_020_Otranto,_Stadtstrand.jpg", "b": "Falk2", "l": "CC BY-SA 4.0"}, {"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Otranto_-_Seafront_-_04.jpg/960px-Otranto_-_Seafront_-_04.jpg", "p": "https://commons.wikimedia.org/wiki/File:Otranto_-_Seafront_-_04.jpg", "b": "Benjamin Smith", "l": "CC BY-SA 4.0"}]}, {"stop": 6, "area": "Salerno", "name": "Lungomare Trieste (seafront promenade)", "what": "A wide, flat promenade about 1 km long that runs the full length of the centre, with palms, gardens, plenty of benches and views over the Amalfi Coast. It is the classic evening passeggiata. The seawall here is mostly rocks, and the sand beach is at the west end (Santa Teresa).", "from": "B&B Salernoway, Via SS. Martiri Salernitani 31", "how": "Walk about 1.0 km, around 13 min south-west down to the sea.", "lat": 40.6762104, "lon": 14.7616191, "photos": [{"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/SalernoSeaPromenade.jpg/960px-SalernoSeaPromenade.jpg", "p": "https://commons.wikimedia.org/wiki/File:SalernoSeaPromenade.jpg", "b": "SOLOXSALERNO (Italian Wikipedia)", "l": "CC BY-SA 3.0"}, {"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Lungomare_Trieste.jpg/960px-Lungomare_Trieste.jpg", "p": "https://commons.wikimedia.org/wiki/File:Lungomare_Trieste.jpg", "b": "Golfodisalerno", "l": "CC BY-SA 4.0"}]}, {"stop": 6, "area": "Salerno", "name": "Spiaggia di Santa Teresa", "what": "Salerno's central free beach: a short strip of dark sand (about 200 m) at the west end of the Lungomare, beside Piazza della Libertà. Showers and a fountain, bars close by, and views to the Amalfi Coast. You can walk to it along the flat promenade.", "from": "B&B Salernoway, Via SS. Martiri Salernitani 31", "how": "Walk about 1.5 km, around 20 min. Go down to the seafront, then west along the flat Lungomare Trieste to its end.", "lat": 40.6773263, "lon": 14.7561703, "photos": [{"i": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Lungomare_Trieste_%28foto_di_Peppe_Pepe_di_Angri%29_-_panoramio.jpg/960px-Lungomare_Trieste_%28foto_di_Peppe_Pepe_di_Angri%29_-_panoramio.jpg", "p": "https://commons.wikimedia.org/wiki/File:Lungomare_Trieste_(foto_di_Peppe_Pepe_di_Angri)_-_panoramio.jpg", "b": "Giuseppe Pepe", "l": "CC BY 3.0"}]}];
